import{_ as o}from"./chunks/2.BRgDBKom.js";import{_ as a,o as r,c as i,am as s}from"./chunks/framework.CenUaW7a.js";const t="/projects/AiMechaM1/en/advanced-kit/assets/12.1.DFYaq1II.webp",n="/projects/AiMechaM1/en/advanced-kit/assets/image85.CY1BkByw.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image86.hgtPr4bo.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image87.maHhLsG5.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image88.D85364z1.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image89.NMjs76HH.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image90.BIdDS5Ok.png",g="/projects/AiMechaM1/en/advanced-kit/assets/12.2.DgVn2GDK.webp",u="/projects/AiMechaM1/en/advanced-kit/assets/image129.EcJjSGfl.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image130.CwvjLWFF.png",P=JSON.parse('{"title":"3.12 Lesson 12: Advanced Line-Following Innovation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.12 Lesson 12 Advanced Line-Following Innovation.md","filePath":"docs/3. Course materials/3.12 Lesson 12 Advanced Line-Following Innovation.md"}'),f={name:"docs/3. Course materials/3.12 Lesson 12 Advanced Line-Following Innovation.md"};function w(b,e,v,y,k,_){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-12-lesson-12-advanced-line-following-innovation" tabindex="-1">3.12 Lesson 12: Advanced Line-Following Innovation <a class="header-anchor" href="#_3-12-lesson-12-advanced-line-following-innovation" aria-label="Permalink to &quot;3.12 Lesson 12: Advanced Line-Following Innovation&quot;">​</a></h1><h2 id="_3-12-1-lesson-introduction" tabindex="-1">3.12.1 Lesson Introduction <a class="header-anchor" href="#_3-12-1-lesson-introduction" aria-label="Permalink to &quot;3.12.1 Lesson Introduction&quot;">​</a></h2><p>As part of the embodied AI large model curriculum series, this lesson builds upon single-sensor line following by introducing function encapsulation and a rear 6-channel line follower sensor to achieve front-and-rear coordination. Taking inspiration from &quot;boundary-halting scenarios&quot;, the black line is treated as a cliff boundary. Following the progression of &quot;rear line following → function encapsulation → motion modularization → front-and-rear boundary avoidance → program optimization&quot;, this lesson practices reverse line following with the rear sensor, explains function encapsulation, packages basic movements into custom functions, and combines dual sensors for boundary detection and automatic U-turns, elevating both advanced line-following applications and structured programming thinking.</p><h2 id="_3-12-2-learning-objectives" tabindex="-1">3.12.2 Learning Objectives <a class="header-anchor" href="#_3-12-2-learning-objectives" aria-label="Permalink to &quot;3.12.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the core purpose and programming value of function encapsulation. Master the definition and invocation methods of custom functions. Understand the collaborative working principle of front and rear line follower sensors, and master the judgment logic for the three boundary-halting states.</p><p><strong>2.</strong> Implement reverse line following using the rear 6-channel line follower sensor. Master the creation and definition of custom functions, and proficiently apply function calls to simplify the main program structure.</p><p><strong>3.</strong> Establish structured thinking for modular programming. Cultivate design capabilities in code abstraction and encapsulation. Strengthen judgment logic for multi-sensor data fusion, and form an initial awareness of layered program architecture design.</p><p><strong>4.</strong> Understand the vital value of modular programming in large-scale software development and stimulate interest in software engineering principles.</p><h2 id="_3-12-3-preparation" tabindex="-1">3.12.3 Preparation <a class="header-anchor" href="#_3-12-3-preparation" aria-label="Permalink to &quot;3.12.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Core Concept Description</strong>:</p><p><strong>Function Encapsulation</strong>: Function encapsulation is like packaging frequently used code into a labeled box by grouping a sequence of repeated blocks under a custom name, allowing the entire sequence to be executed simply by calling that function name. This reduces duplicate code, simplifies modifications, and keeps the program structure clear.</p><p><strong>Difference Between Front and Rear Sensors</strong>: The front sensor faces the front of the car to detect road conditions while driving forward, whereas the rear sensor faces the back of the car to detect road conditions while reversing. Both sensors follow the same probe numbering rule, but their steering logic is reversed when moving in opposite directions.</p><p><strong>Three Boundary-Halting States</strong>:</p><ul><li><p><strong>Forward Driving State</strong>: Both the front and rear sensors detect the white background inside the safe zone, and the car drives forward normally.</p></li><li><p><strong>Move Forward and U-Turn</strong>: When the rear sensor detects the black boundary line indicating the cliff edge ahead, the car moves forward briefly and spins in place to make a U-turn.</p></li><li><p><strong>Move Backward and U-Turn</strong>: When the front sensor detects the black boundary line indicating the cliff edge behind, the car moves backward briefly and spins in place to make a U-turn.</p></li></ul><p><strong>Hardware Port</strong>: Connect the front 6-channel line follower sensor to port J, and connect the rear 6-channel line follower sensor to its corresponding port.</p><h2 id="_3-12-4-hands-on-project" tabindex="-1">3.12.4 Hands-On Project <a class="header-anchor" href="#_3-12-4-hands-on-project" aria-label="Permalink to &quot;3.12.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project implements a boundary-constrained driving function for the Mecanum-wheel car, adopting a dual-sensor detection and modular function control architecture. Using both front and rear 6-channel line follower sensors, the system monitors ground boundary states at the front and rear of the chassis in real time. Multi-layer conditional judgments distinguish among three operating conditions: safe forward driving, front boundary U-turn, and rear boundary U-turn, packaging the corresponding motion sequences into independent custom functions. The main program calls these functions as needed to complete autonomous control with clean and concise logic, keeping the car driving continuously within the oval boundary and automatically making a U-turn whenever it touches the black line without exiting the designated area.</p><img loading="lazy" height="540" width="960" src="'+t+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="616" width="1196" src="'+n+'" class="common_img" style="width:600px;aspect-ratio:1196 / 616;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Function definition</td><td style="text-align:center;"><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:400px;aspect-ratio:1920 / 1040;"></td><td style="text-align:left;">Creates a custom function.</td></tr><tr><td style="text-align:center;">Function definition</td><td style="text-align:center;"><img loading="lazy" height="644" width="833" src="'+c+'" class="common_img" style="width:400px;aspect-ratio:833 / 644;"></td><td style="text-align:left;">Defines the specific execution blocks inside the custom function.</td></tr><tr><td style="text-align:center;">Sensor reading</td><td style="text-align:center;"><img loading="lazy" height="153" width="712" src="'+d+'" class="common_img" style="width:400px;aspect-ratio:712 / 153;"></td><td style="text-align:left;">Reads the state of the front or rear line follower sensor.</td></tr><tr><td style="text-align:center;">Logical operation</td><td style="text-align:center;"><img loading="lazy" height="89" width="298" src="'+p+'" class="common_img" style="width:160px;aspect-ratio:298 / 89;"></td><td style="text-align:left;">Jointly evaluates the states of both the front and rear sensors.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Autonomous Reverse Line Following with the Rear Sensor</strong></p><ul><li><p>Trigger condition: Start the program when the A key is short-pressed, running inside a repeat forever loop.</p></li><li><p>Use the rear 6-channel line follower sensor for detection and judgment.</p></li><li><p>Set the rotational wheel speeds to negative values to achieve reverse line following.</p></li><li><p>Straight driving state: Set both the left and right wheel groups to -40 rpm to drive straight backward.</p></li><li><p>Adjust the backward rotational speed differential between the left and right wheel groups according to left or right deviations.</p></li><li><p>Functional purpose: Master the usage of the rear sensor and understand the steering logic during backward driving.</p></li></ul><img loading="lazy" height="680" width="1160" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:1160 / 680;"><img loading="lazy" height="540" width="960" src="'+g+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p><strong>Task 2: Function Encapsulation for Basic Movements</strong></p><ul><li><p>Create three custom functions: Move Forward, Forward and U-Turn, and Backward and U-Turn.</p></li><li><p>Move forward function: Set both the left and right wheel groups to drive forward at a constant rotational speed of 40 rpm.</p></li><li><p>Forward and U-Turn function: Drive forward for a short distance. → Spin right in place at 40 rpm. → Resume forward driving once the turn is complete.</p></li><li><p>Backward and U-Turn function: Drive backward for a short distance. → Spin left in place at 40 rpm. → Resume forward driving once the turn is complete.</p></li><li><p>Once function encapsulation is complete, the main program only needs to call the function names, keeping the code concise and clear.</p></li></ul><img loading="lazy" height="320" width="1121" src="'+u+'" class="common_img" style="width:700px;aspect-ratio:1121 / 320;"><p><strong>Task 3: Basic Boundary Avoidance Program</strong></p><ul><li><p>Trigger condition: Start the program when the A key is short-pressed, running inside an outer repeat forever loop.</p></li><li><p>Condition 1: When both the front sensor and the rear sensor detect the white background. → Call the move forward function.</p></li><li><p>Condition 2: When front Probe 1 does not detect a black line and front Probe 6 detects a black line. → Call the backward and U-turn function.</p></li><li><p>Condition 3: When rear Probe 1 does not detect a black line and rear Probe 6 detects a black line. → Call the forward and U-turn function.</p></li><li><p>Overall outcome: The car drives within the oval ring and automatically makes a U-turn whenever it touches the black boundary line, remaining inside the ring at all times.</p></li></ul><img loading="lazy" height="421" width="1176" src="'+m+'" class="common_img" style="width:700px;aspect-ratio:1176 / 421;"><p><strong>Task 4: Optimized Boundary Avoidance Program</strong></p><ul><li><p>Add more probe state judgment conditions to cover a wider range of boundary detection scenarios.</p></li><li><p>Add separate detections for the left boundary and right boundary, triggering U-turn maneuvers in the corresponding directions.</p></li><li><p>Add intermediate state judgments for Probe 2 and Probe 5 to improve boundary detection sensitivity.</p></li><li><p>Optimization outcome: Achieves more accurate boundary detection and faster response times, preventing the car from crossing the boundary or making false U-turns.</p></li></ul><img loading="lazy" height="616" width="1196" src="'+n+'" class="common_img" style="width:700px;aspect-ratio:1196 / 616;"><img loading="lazy" height="540" width="960" src="'+t+'" class="common_img" style="width:700px;aspect-ratio:960 / 540;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Advanced Line Following Innovation</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+o+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-12-5-expansion-and-advancement" tabindex="-1">3.12.5 Expansion and Advancement <a class="header-anchor" href="#_3-12-5-expansion-and-advancement" aria-label="Permalink to &quot;3.12.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Timed Area Patrol</strong></p><p>Add a timer variable to the boundary avoidance program to track the continuous driving time of the car inside the ring, playing a prompt tone and switching the RGB LED every 30 s. Record the total number of U-turns to practice the comprehensive application of variable counting and timing control.</p><p><strong>Project 2: Dual-Sensor Precision Backward Parking</strong></p><p>Utilize both the front and rear sensors to implement precision reverse parking. Use the front sensor to follow the line into the parking aisle while driving forward, and switch to the rear sensor while reversing to accurately guide the car into the parking space, practicing front-and-rear sensor switching and multi-stage task programming.</p><h2 id="_3-12-6-q-a" tabindex="-1">3.12.6 Q&amp;A <a class="header-anchor" href="#_3-12-6-q-a" aria-label="Permalink to &quot;3.12.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is the primary purpose of encapsulating car movements into custom functions in the boundary avoidance program?</strong></p><p><strong>Answer</strong>: The primary purpose is to reduce duplicate code and improve program maintainability.</p><p><strong>Q2: What is the core advantage of using dual front and rear line follower sensors compared to a single sensor?</strong></p><p><strong>Answer</strong>: The core advantage is that the front sensor anticipates the route ahead while the rear sensor verifies the trajectory behind, working in coordination to reduce derailment and improve tracking accuracy.</p><h2 id="_3-12-7-technical-support-and-discussion" tabindex="-1">3.12.7 Technical Support and Discussion <a class="header-anchor" href="#_3-12-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.12.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',58)])])}const C=a(f,[["render",w]]);export{P as __pageData,C as default};
